<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/payment.php';require_once __DIR__.'/../lib/razorpay.php';
send_cors_headers();$auth=require_auth();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$attemptId=trim((string)($body['payment_attempt_id']??''));$providerOrderId=trim((string)($body['razorpay_order_id']??''));$providerPaymentId=trim((string)($body['razorpay_payment_id']??''));$signature=trim((string)($body['razorpay_signature']??''));if($attemptId===''||$providerOrderId===''||$providerPaymentId===''||$signature==='')json_response(422,['success'=>false,'message'=>'Razorpay payment details are incomplete.']);$db=get_db();$db->beginTransaction();try{$stmt=$db->prepare('SELECT p.*,o.user_id,o.payment_status FROM payment_attempts p JOIN orders o ON o.id=p.order_id WHERE p.id=:id AND o.user_id=:user FOR UPDATE');$stmt->execute(['id'=>$attemptId,'user'=>auth_user_id($auth)]);$attempt=$stmt->fetch();if(!$attempt||$attempt['provider']!=='online')json_response(404,['success'=>false,'message'=>'Payment attempt not found.']);if($attempt['provider_order_id']!==$providerOrderId)json_response(409,['success'=>false,'message'=>'Razorpay order does not match this checkout.']);$expected=APP_ENV==='local'&&str_starts_with($providerOrderId,'mock_')?hash_hmac('sha256',$providerOrderId.'|'.$providerPaymentId,APP_KEY):razorpay_signature($providerOrderId,$providerPaymentId);if(!hash_equals($expected,$signature))json_response(400,['success'=>false,'message'=>'Razorpay signature verification failed.']);if($attempt['payment_status']==='paid'){$db->commit();json_response(200,['success'=>true,'message'=>'Payment was already verified.']);}confirm_online_order((int)$attempt['order_id'],$providerPaymentId);$db->commit();json_response(200,['success'=>true,'message'=>'Payment verified and order confirmed.','order_id'=>(int)$attempt['order_id']]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
